private val OoroYellow = Color(0xFFDFFF00)
private val OoroBackground = Color(0xFFF7F7F4)

class MainActivity : ComponentActivity() {
    private val vm: DriverAppViewModel by viewModels { DriverAppViewModel.factory(applicationContext) }
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); setContent { OoroTheme { DriverRoot(vm) } } }
}

@Composable private fun OoroTheme(content: @Composable () -> Unit) {
    val dark = isSystemInDarkTheme()
    val colors = if (dark) {
        darkColorScheme(primary = OoroYellow, onPrimary = Color.Black, secondary = OoroYellow, background = Color(0xFF111411), surface = Color(0xFF1B201B), onSurface = Color(0xFFF3F5EF))
    } else {
        lightColorScheme(primary = Color.Black, secondary = OoroYellow, background = OoroBackground, surface = Color.White)
    }
    MaterialTheme(colorScheme = colors, content = content)
}
@Composable private fun DriverRoot(vm: DriverAppViewModel) {
    val mode by vm.mode.collectAsState()
    Box(Modifier.fillMaxSize()) {
        if (BuildConfig.USE_MOCK_BACKEND) {
            Surface(color = OoroYellow, modifier = Modifier.fillMaxWidth().align(Alignment.TopCenter)) {
                Text("LOCAL MOCK MODE · NO REAL DRIVER DATA", modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp), fontSize = 12.sp, fontWeight = FontWeight.Bold, color = Color.Black)
            }
        }
        when (mode) {
            AppMode.LOGIN, AppMode.OTP -> DriverWelcomeScreen(vm, mode)
            AppMode.FLEET_INQUIRY -> FleetInquiry(vm)
            AppMode.ONBOARDING -> OnboardingScreen(vm)
            AppMode.DASHBOARD -> DriverDashboardV2(vm)
        }
    }
}

